import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Farmer marks an order as shipped — used when they post/hand it off to the
// buyer themselves. Valid on any farmer-fulfilled order: self-pickup, courier,
// or a home delivery that is NOT in the rider flow (no rider assigned). Stamps
// shipped_at, so the buyer sees the Shipped → Delivered timeline. The order
// STAYS in Active Orders (not yet resolved) until the buyer confirms via the
// consumer "Delivered" route (which stamps received_at, or collected_at for a
// self-pickup). Shipping is a trust-based marker — it does NOT close the order,
// so no handover code is needed here; only the buyer's confirmation does.
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, farmer_id, status, delivery_type, delivery_status, shipped_at, collected_at')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.farmer_id !== session.farmerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // A home delivery that's already with a rider is closed at the door by the
  // rider, not shipped by the farmer. Home deliveries with no rider assigned are
  // farmer-fulfilled, so the farmer ships them like a courier order.
  if (order.delivery_type === 'home_delivery'
    && order.delivery_status != null
    && order.delivery_status !== 'unassigned') {
    return NextResponse.json({ error: 'A rider is handling this delivery.' }, { status: 409 })
  }
  if (order.status !== 'approved') {
    return NextResponse.json({ error: 'Confirm the order before marking it shipped.' }, { status: 409 })
  }
  if (order.collected_at) {
    return NextResponse.json({ error: 'This order was already picked up.' }, { status: 409 })
  }
  if (order.shipped_at) {
    return NextResponse.json({ error: 'This order is already marked shipped.' }, { status: 409 })
  }

  const { data: updated, error: updErr } = await supabase
    .from('orders')
    .update({ shipped_at: new Date().toISOString() })
    .eq('id', id)
    .eq('farmer_id', session.farmerId)
    .eq('status', 'approved')
    .is('shipped_at', null)
    .is('collected_at', null)
    .select('id, shipped_at')

  if (updErr) {
    console.error('[YFF farmer/ship] update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not mark shipped. Please try again.' }, { status: 500 })
  }
  if (!updated || updated.length === 0) {
    return NextResponse.json({ error: 'Could not mark shipped. Refresh and try again.' }, { status: 409 })
  }

  return NextResponse.json({ ok: true, shipped_at: updated[0].shipped_at })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Buyer confirms delivery themselves — the farmer no longer closes orders. For
// every farmer-fulfilled type the farmer first marks it shipped (shipped_at), then
// the buyer taps "Delivered" here:
//   • self-pickup → collected_at
//   • courier / farmer-shipped home delivery → received_at
// Rider-driven home deliveries never set shipped_at (they use delivered_at) and
// are closed by the rider, so they're naturally excluded here. Either stamp
// resolves the order and moves it to history on both sides.
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, consumer_id, status, delivery_type, shipped_at, collected_at, received_at')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  if (order.status !== 'approved') {
    return NextResponse.json({ error: 'This order is not ready to confirm.' }, { status: 409 })
  }
  if (!order.shipped_at) {
    return NextResponse.json({ error: 'This order has not been shipped yet.' }, { status: 409 })
  }

  // Self-pickup: the buyer confirms collection → collected_at.
  const isPickup = order.delivery_type === 'self_pickup' || !order.delivery_type
  if (isPickup) {
    if (order.collected_at) {
      return NextResponse.json({ error: 'This order is already marked picked up.' }, { status: 409 })
    }
    const { data: updated, error: updErr } = await supabase
      .from('orders')
      .update({ collected_at: new Date().toISOString() })
      .eq('id', id)
      .eq('consumer_id', session.consumerId)
      .eq('status', 'approved')
      .not('shipped_at', 'is', null)
      .is('collected_at', null)
      .select('id, collected_at')

    if (updErr) {
      console.error('[YFF consumer/received] pickup update failed:', updErr.message)
      return NextResponse.json({ error: 'Could not confirm pickup. Please try again.' }, { status: 500 })
    }
    if (!updated || updated.length === 0) {
      return NextResponse.json({ error: 'Could not confirm pickup. Refresh and try again.' }, { status: 409 })
    }
    return NextResponse.json({ ok: true, collected_at: updated[0].collected_at })
  }

  // Courier / farmer-shipped home delivery: the buyer confirms receipt →
  // received_at, but only once the farmer has marked it shipped.
  if (order.delivery_type !== 'courier' && order.delivery_type !== 'home_delivery') {
    return NextResponse.json({ error: 'This order is not confirmed this way.' }, { status: 409 })
  }
  if (!order.shipped_at) {
    return NextResponse.json({ error: 'This order has not been shipped yet.' }, { status: 409 })
  }
  if (order.received_at) {
    return NextResponse.json({ error: 'This order is already marked received.' }, { status: 409 })
  }

  const { data: updated, error: updErr } = await supabase
    .from('orders')
    .update({ received_at: new Date().toISOString() })
    .eq('id', id)
    .eq('consumer_id', session.consumerId)
    .not('shipped_at', 'is', null)
    .is('received_at', null)
    .select('id, received_at')

  if (updErr) {
    console.error('[YFF consumer/received] update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not confirm receipt. Please try again.' }, { status: 500 })
  }
  if (!updated || updated.length === 0) {
    return NextResponse.json({ error: 'Could not confirm receipt. Refresh and try again.' }, { status: 409 })
  }

  return NextResponse.json({ ok: true, received_at: updated[0].received_at })
}

if (!listings || listings.length !== listingIds.length) {
  return bad('One or more items in your cart are no longer available.')
}

const listingById = new Map(listings.map((l) => [l.id, l]))
const rows: Array<Record<string, unknown>> = []
let total = 0
// One OTP for the whole batch. Home delivery: the rider does a single
// handover at the door. Self-pickup: the customer reads it to the farmer at
// collection. Either way the whole checkout shares one code.
const sharedHandoverOtp = generateHandoverOtp()
const deliveryFee = deliveryType === 'home_delivery' ? DELIVERY_FEE_RUPEES : 0

// Validate first (price + ownership) before we touch any stock. Stock
// claims happen below with the RPC so two cart submits can't oversell.
for (const item of items) {
  const listing = listingById.get(item.listingId)
  if (!listing) return bad('Item missing.')
  if (listing.farmer_id !== farmerId) return bad('Items must belong to the same farmer.')
  // Block ordering a listing the farmer (or moderator) has taken down. A
  // stale cart could still hold a since-paused/suspended item; only
  // 'available' produce may be purchased.
  if (listing.status !== 'available') {
    return bad(`${listing.name} is no longer available.`)
  }

  const unitPrice = getTierPrice(item.qty, {
    priceTier1Qty: listing.price_tier_1_qty,
    priceTier1Price: listing.price_tier_1_price,
    priceTier2Qty: listing.price_tier_2_qty,
    priceTier2Price: listing.price_tier_2_price,
    priceTier3Price: listing.price_tier_3_price,
  })

  const linePrice = unitPrice != null ? Math.round(unitPrice * item.qty) : null
  if (linePrice == null || linePrice <= 0) {
    return bad(`Price not set for ${listing.name}. Please ask the farmer.`)
  }
  total += linePrice

  rows.push({
    farmer_id: farmerId,
    produce_listing_id: listing.id,
    produce_name: listing.name,
    quantity: item.qty,
    unit: listing.unit || 'kg',
    total_price: linePrice,
    buyer_name: buyerName,
    buyer_phone: buyerPhone,
    buyer_email: buyerEmail,
    consumer_id: buyerId,
    idempotency_key: idempotencyKey,
    pickup_location: typeof pickupLocation === 'string' ? pickupLocation.slice(0, 200) : null,
    status: 'pending',
    payment_method: paymentMethod,
    payment_status: 'pending',
    delivery_type: deliveryType,
    delivery_status: deliveryType === 'home_delivery' ? 'unassigned' : null,
    delivery_address: deliveryAddress,
    delivery_city: deliveryCity,
    delivery_landmark: deliveryLandmark,
    delivery_pincode: deliveryPincode,
    delivery_alt_phone: deliveryAltPhone,
    handover_otp: sharedHandoverOtp,
    // Fee is paid once per cart, so we stamp it on the first row only.
    // sum(delivery_fee) and sum(rider_payout) over a batch === one fee.
    delivery_fee: 0,
    rider_payout: 0,
  })
}

if (rows.length > 0 && deliveryFee > 0) {
  rows[0].delivery_fee = deliveryFee
  rows[0].rider_payout = deliveryFee
}

// Platform fee (moderator commission) — a % of the cart subtotal, added on top
// and stamped once per batch (first row), mirroring delivery_fee. Resolved
// server-side; 0 unless the moderator has set a fee. Only written when > 0, so
// the column is never referenced before its migration runs.
const feePercent = await getPlatformFeePercent(supabase)
const platformFee = computePlatformFee(total, feePercent)
if (rows.length > 0 && platformFee > 0) {
  rows[0].platform_fee = platformFee
}

// Atomic stock claim. decrement_stock returns false if the listing went
// below zero (or vanished). On any failure we revert prior claims so we
// don't leak inventory.
const claimed: Array<{ listingId: string; qty: number }> = []

