    credentials: 'same-origin',
  }).catch(() => null)
  if (r && r.ok) await refresh()
  else alert(L('Could not confirm. Please try again.', 'ధృవీకరించలేకపోయాం. మళ్ళీ ప్రయత్నించండి.'))
  setBusyId(null)
}, [refresh, L])

